def match(orders):
    import heapq

    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> dict(side, price, qty, seq, active)
    trades = []
    seq_counter = 0

    def add_resting(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        seq_counter += 1
        seq = seq_counter
        remaining = qty

        heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and heap:
            top = heap[0]
            top_id = top[2]

            if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                heapq.heappop(heap)
                continue

            top_price = book[top_id]['price']

            if typ != 'market' and price is not None:
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, book[top_id]['qty'])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            book[top_id]['qty'] -= trade_qty

            if book[top_id]['qty'] == 0:
                book[top_id]['active'] = False
                heapq.heappop(heap)
            # else: partially filled resting order keeps its place (stays at heap top)

        if typ == 'limit' and remaining > 0:
            add_resting(oid, side, price, remaining, seq)
        # ioc/market discard any remainder

    return trades

